def resolve(path, cwd, links):
    if not path or not cwd or links is None:
        return None

    # Start with the initial path
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    max_links = 8
    i = 0

    while i < len(components):
        component = components[i]

        # Skip empty components and '.'
        if component == '' or component == '.':
            i += 1
            continue

        # Handle '..'
        if component == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component to current path
        if current == '/':
            new_path = '/' + component
        else:
            new_path = current + '/' + component

        # Check if this path is a symlink
        if new_path in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[new_path]

            # Parse the target
            if target.startswith('/'):
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Target is relative to the directory containing the link
                if current == '/':
                    current = '/'
                else:
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                target_components = target.split('/')

            # Replace current components with target components + remaining components
            components = target_components + components[i+1:]
            i = 0
        else:
            current = new_path
            i += 1

    return current

